CREATE   view   dbo.stuf_def_nfani as  SELECT     dbo.STUF_DEF.CODE, dbo.STUF_DEF.NAME, dbo.STUF_DEF.N_FANI, LEFT(N_FANI, 2) as col1, SUBSTRING(N_FANI,3 ,2) AS col2, SUBSTRING(N_FANI,5 ,3) AS col3, SUBSTRING(N_FANI,8 ,2) AS col4, SUBSTRING(N_FANI,10 ,1) AS col5, SUBSTRING(N_FANI,11 ,2) AS col6, 1 AS col7, 1 AS col8, 1 AS col9 , TCOD_MAP_1.MPNAME AS colN1, TCOD_MAP_2.MPNAME AS colN2, TCOD_MAP_3.MPNAME AS colN3, TCOD_MAP_4.MPNAME AS colN4, TCOD_MAP_5.MPNAME AS colN5, TCOD_MAP_6.MPNAME AS colN6, ' '  AS colN7, ' '  AS colN8, ' '  AS colN9 FROM     dbo.STUF_DEF   INNER Join dbo.TCOD_MAP TCOD_MAP_1 ON { fn LEFT(dbo.STUF_DEF.N_FANI, 2) } = TCOD_MAP_1.MPCODE INNER Join dbo.TCOD_MAP TCOD_MAP_2 ON  SUBSTRING(N_FANI,3 ,2) = TCOD_MAP_2.MPCODE INNER Join dbo.TCOD_MAP TCOD_MAP_3 ON  SUBSTRING(N_FANI,5 ,3) = TCOD_MAP_3.MPCODE INNER Join dbo.TCOD_MAP TCOD_MAP_4 ON  SUBSTRING(N_FANI,8 ,2) = TCOD_MAP_4.MPCODE INNER Join dbo.TCOD_MAP TCOD_MAP_5 ON  SUBSTRING(N_FANI,10 ,1) = TCOD_MAP_5.MPCODE INNER Join dbo.TCOD_MAP TCOD_MAP_6 ON  SUBSTRING(N_FANI,11 ,2) = TCOD_MAP_6.MPCODE WHERE (TCOD_MAP_1.MPP = 1) AND (TCOD_MAP_2.MPP = 2) AND (TCOD_MAP_3.MPP = 3) AND (TCOD_MAP_4.MPP = 4) AND (TCOD_MAP_5.MPP = 5) AND (TCOD_MAP_6.MPP = 6)
